using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
        // Existing documents use "Discriminator", so we must keep the old name.
        modelBuilder.Entity<Blog>().HasDiscriminator().HasValue("Blog");
        modelBuilder.Entity<Blog>()
            .Property<string>("$type")
            .ToJsonProperty("Discriminator");

        // Breaking change 2: EF Core 9 changed the id format from
        // "Discriminator|Key" to just "Key". Existing documents use "Blog|1",
        // so we opt back into the legacy format.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>()
            .Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdValueGenerator>();

        // Breaking change 3: Cosmos DB provider does not support indexes
        // defined via HasIndex. This was silently ignored before but now
        // throws in EF Core 9. Remove the HasIndex call.
        // (The previous HasIndex(b => b.Name) has been deleted.)
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // Breaking change 4: EF Core 9 uses the newer Cosmos SDK with
        // a gateway-mode default. Sync I/O now throws by default.
        // The SyncJob class calls .ToList() and .SaveChanges()
        // synchronously, so either convert to async or opt-in below.
        // Here we keep the sync calls and will fix SyncJob to use async.
        base.OnConfiguring(options);
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

// Value generator that reproduces the EF Core 8 "Discriminator|Key" id format
// so that existing documents remain addressable.
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyCosmosIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
    {
        var discriminator = entry.Metadata.GetDiscriminatorValue()?.ToString() ?? entry.Metadata.ShortName();
        var key = entry.Property("Id").CurrentValue?.ToString();
        return $"{discriminator}|{key}";
    }
}

